import{_ as e,o,c as s,ag as n}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"es/car-wash/index.md","filePath":"es/car-wash/index.md"}'),i={name:"es/car-wash/index.md"};function r(t,a,l,d,c,u){return o(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>Entra con el coche, elige un programa y el vehículo avanza entre cepillos giratorios, espuma, arcos de aclarado y un secador de vapor, mientras todos los que están alrededor ven el mismo lavado. A pie, los jugadores cogen una hidrolimpiadora y quitan la suciedad nivel a nivel. Cada ubicación se coloca en el juego y cada ajuste se edita en el juego.</p><h2 id="funciones" tabindex="-1">Funciones <a class="header-anchor" href="#funciones" aria-label="Permalink to &quot;Funciones&quot;">​</a></h2><ul><li><strong>Túneles de lavado</strong>: cepillos ajustados al ancho del vehículo, arcos de jabón y de aclarado, secador de vapor, sincronizados para todos los jugadores cercanos. Consulta <a href="/es/car-wash/tunnels">Túneles</a>.</li><li><strong>Programas de lavado</strong>: nombre, precio, velocidad y qué pasos se ejecutan (jabón, aclarado, secado, cera). La cera mantiene el vehículo limpio todo el tiempo que elijas.</li><li><strong>Hidrolimpiadoras</strong> en cualquier prop del mundo que indiques, o en estaciones que colocas tú, con pago por nivel de suciedad. Consulta <a href="/es/car-wash/pressure-washers">Hidrolimpiadoras</a>.</li><li><strong>Editor de túneles en el juego</strong>: crea un túnel donde estás o copia un lavadero del juego base, mueve cada pieza con el teclado y guarda.</li><li><strong>Todo en <code>/nay</code></strong>: precios, programas, descuentos por trabajo, cuenta de pago, clases de vehículo bloqueadas, blips con selector visual de icono y de color. Consulta <a href="/es/car-wash/settings">Ajustes</a>.</li><li><strong>Justo y seguro</strong>: un vehículo por túnel, comprobaciones de sentido contrario y de carril bloqueado, pagos y reserva del túnel validados en el servidor.</li><li><strong>Descuentos por trabajo</strong> y un porcentaje de precio por túnel. Los jugadores pagan en efectivo, con el banco, o en efectivo y luego con el banco.</li><li><strong>Adaptado al mapa</strong>: los cepillos estáticos del mapa se ocultan a lo largo de cada túnel y vuelven cuando el recurso se detiene. En Strawberry, los archivos de mapa sin cepillos sustituyen al lavadero original.</li><li><strong>API HTTP y webhooks</strong>: historial de lavados y estadísticas para tu web o tu bot, un mensaje de Discord por cada lavado. Consulta <a href="/es/car-wash/api">API y webhooks</a>.</li><li><strong>Seis idiomas</strong>: inglés, francés, español, portugués, polaco, alemán.</li></ul><h2 id="compatibilidad" tabindex="-1">Compatibilidad <a class="header-anchor" href="#compatibilidad" aria-label="Permalink to &quot;Compatibilidad&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detectados automáticamente.</li><li>Target (opcional, para las hidrolimpiadoras): ox_target o qb-target. Sin target, los jugadores usan un aviso de tecla.</li><li>Dependencias: oxmysql y <code>nay_lib</code> (incluido con tu compra).</li></ul><h2 id="rendimiento" tabindex="-1">Rendimiento <a class="header-anchor" href="#rendimiento" aria-label="Permalink to &quot;Rendimiento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Estado</th><th>Cliente (resmon)</th></tr></thead><tbody><tr><td>En reposo</td><td>0,00 ms</td></tr><tr><td>Lavando un vehículo</td><td>unos 0,08 ms</td></tr></tbody></table><p>Medido con resmon en la game build 3751.</p><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Todos los pasos en la página <a href="/es/getting-started">Primeros pasos</a>. Después concédete <code>nay_car_wash.config</code> (o <code>nay.admin</code>) y abre <code>/nay</code>. Hay dos túneles listos desde el principio: Strawberry y Little Seoul.</p>`,12)])])}const g=e(i,[["render",r]]);export{h as __pageData,g as default};
